command:
// Open Legend Unofficial — Apply Bane / Boon
// Pick any bane or boon from the compendiums, choose a power level, and apply it
// to every TARGETED or SELECTED token (your choice in the dialog).
const { DialogV2 } = foundry.applications.api;
const ol = game.openlegend;
if ( !ol?.applyBaneByTokenUuid || !ol?.applyBoonByTokenUuid ) {
  ui.notifications?.error("Open Legend Unofficial apply helpers are unavailable.");
  return;
}

// Load both compendium indices with their discrete power levels (from the
// powerEffects rows; falls back to the base power level).
const loadEntries = async (packId, kind) => {
  const pack = game.packs.get(packId);
  if ( !pack ) return [];
  const index = await pack.getIndex({ fields: ["system.powerLevel", "system.powerEffects"] });
  return [...index].map(e => {
    const discrete = (e.system?.powerEffects ?? [])
      .map(p => Math.floor(Number(p.powerLevel)))
      .filter(n => Number.isFinite(n) && (n > 0));
    const base = Math.floor(Number(e.system?.powerLevel) || 0);
    const levels = discrete.length
      ? [...new Set(discrete)].sort((a, b) => a - b)
      : [Math.max(1, base || 1)];
    return { uuid: e.uuid, name: e.name, kind, levels };
  }).sort((a, b) => a.name.localeCompare(b.name));
};
const banes = await loadEntries("tomucatos-open-legend-rpg-system.banes", "bane");
const boons = await loadEntries("tomucatos-open-legend-rpg-system.boons", "boon");
if ( !banes.length && !boons.length ) {
  ui.notifications?.warn("No banes or boons found in the compendiums.");
  return;
}

const esc = s => foundry.utils.escapeHTML?.(s) ?? s;
const optionsFor = list => list.map(e =>
  `<option value="${esc(e.uuid)}" data-kind="${e.kind}" data-levels="${esc(JSON.stringify(e.levels))}">${esc(e.name)}</option>`).join("");
const selectedCount = canvas.tokens?.controlled?.length ?? 0;
const targetedCount = game.user?.targets?.size ?? 0;
const content = `
  <div class="ol-apply-picker">
    <div class="form-group">
      <label>Bane / Boon</label>
      <select name="doc" style="flex:1;">
        <optgroup label="Banes">${optionsFor(banes)}</optgroup>
        <optgroup label="Boons">${optionsFor(boons)}</optgroup>
      </select>
    </div>
    <div class="form-group">
      <label>Power level</label>
      <select name="pl" style="flex:1;"></select>
    </div>
    <div class="form-group" data-potent-row>
      <label>Potent <i class="fas fa-biohazard" title="Potent bane: resist rolls at disadvantage 1."></i></label>
      <input type="checkbox" name="potent"/>
    </div>
    <div class="form-group">
      <label>Apply to</label>
      <select name="mode" style="flex:1;">
        <option value="targeted">All targeted tokens (${targetedCount})</option>
        <option value="selected">All selected tokens (${selectedCount})</option>
      </select>
    </div>
  </div>`;

const result = await DialogV2.wait({
  window: { title: "Apply Bane / Boon" },
  classes: ["openlegend"],
  content,
  rejectClose: false,
  // Keep the power-level choices (and the Potent row) in sync with the picked
  // bane/boon. `dialog` is the app in v13+, the dialog element in v12.
  render: (event, dialog) => {
    const root = dialog?.element ?? dialog;
    const docSel = root.querySelector('select[name="doc"]');
    const plSel = root.querySelector('select[name="pl"]');
    const potentRow = root.querySelector("[data-potent-row]");
    const sync = () => {
      const opt = docSel?.selectedOptions?.[0];
      let levels = [];
      try { levels = JSON.parse(opt?.dataset.levels ?? "[]"); } catch ( _e ) { levels = []; }
      if ( !levels.length ) levels = [1];
      plSel.innerHTML = levels.map((l, i) =>
        `<option value="${l}"${i === 0 ? " selected" : ""}>PL ${l}</option>`).join("");
      if ( potentRow ) potentRow.style.display = (opt?.dataset.kind === "bane") ? "" : "none";
    };
    docSel?.addEventListener("change", sync);
    sync();
  },
  buttons: [
    { action: "apply", label: "Apply", icon: "fas fa-hands-holding", default: true,
      callback: (event, button, dialog) => {
        const root = dialog.element;
        const opt = root.querySelector('select[name="doc"]')?.selectedOptions?.[0];
        return {
          uuid: opt?.value ?? "",
          kind: opt?.dataset.kind ?? "",
          name: (opt?.textContent ?? "").trim(),
          pl: Math.max(1, Math.floor(Number(root.querySelector('select[name="pl"]')?.value) || 1)),
          potent: !!root.querySelector('input[name="potent"]')?.checked,
          mode: root.querySelector('select[name="mode"]')?.value === "selected" ? "selected" : "targeted"
        };
      } },
    { action: "cancel", label: "Cancel", icon: "fas fa-times" }
  ]
});
if ( !result || (typeof result !== "object") || !result.uuid ) return;

const tokens = (result.mode === "selected")
  ? (canvas.tokens?.controlled ?? [])
  : [...(game.user?.targets ?? [])];
if ( !tokens.length ) {
  ui.notifications?.warn(result.mode === "selected"
    ? "Select one or more tokens first, then run this macro."
    : "Target one or more tokens first (targeting tool), then run this macro.");
  return;
}
for ( const token of tokens ) {
  const uuid = token.document?.uuid ?? token.actor?.uuid;
  if ( !uuid ) continue;
  if ( result.kind === "bane" ) await ol.applyBaneByTokenUuid(uuid, result.uuid, result.pl, result.potent);
  else await ol.applyBoonByTokenUuid(uuid, result.uuid, result.pl);
}
ui.notifications?.info(`${result.name} (PL ${result.pl}) applied to ${tokens.length} token${tokens.length === 1 ? "" : "s"}.`);
